import{createHash}from"node:crypto";import{principalIdentity}from"#channel/principal-identity.js";import{TOOL_SESSION_KEY_MAX_LENGTH}from"#channel/invoke-tool.js";const TOOL_SESSION_ID_PREFIX=`tool_session_`;function isToolSessionId(e){return e.startsWith(TOOL_SESSION_ID_PREFIX)}function validateToolSessionKey(e){if(e.length===0)return`The tool session key must not be empty.`;if(e.length>TOOL_SESSION_KEY_MAX_LENGTH)return`The tool session key must be at most ${TOOL_SESSION_KEY_MAX_LENGTH} characters.`}function deriveToolSessionId(e){let t=[`eve.tool-session.v1`,principalIdentity(e.current),e.key];e.forwardedBy!==void 0&&t.push(principalIdentity(e.forwardedBy));let n=JSON.stringify(t);return`${TOOL_SESSION_ID_PREFIX}${createHash(`sha256`).update(n,`utf8`).digest(`hex`)}`}export{TOOL_SESSION_ID_PREFIX,deriveToolSessionId,isToolSessionId,validateToolSessionKey};